using FlexExtractor;
static partial class Cases {
 static string Source(Config c,string relative="partProcessed/Request_one.xml",string text="<root><header timeStamp='2026-01-01'/></root>"){var p=Path.Combine(c.WatchRoot,DateTime.Now.ToString("yyyy/MM/dd"),"0031_1_1",relative);Directory.CreateDirectory(Path.GetDirectoryName(p)!);File.WriteAllText(p,text);return p;}
 static object Scan(Config c,string operation="scan",DateTime? baseline=null){var t=typeof(Config).Assembly.GetType("FlexExtractor.Scanner");Program.Check(t!=null,"isolatable scanner missing");return Invoke(t!,"Run",null,c,operation,baseline??DateTime.UtcNow,Path.Combine(Path.GetDirectoryName(c.WatchRoot)!,"cursor.json"))!;}
 public static void TestBatchBoundedAndResumes(){var c=Cfg(Fresh());c.MaxFilesPerPass=2;for(var i=0;i<7;i++)Source(c,$"partProcessed/Request_{i}.xml");Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==2,"batch unbounded");for(var i=0;i<5;i++)Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==7,"cursor starves later files");}
 public static void TestOnlyNewAndRetentionUseNewestTimestamp(){var c=Cfg(Fresh());c.OnlyNewAfterStart=true;var s=Source(c);File.SetCreationTimeUtc(s,DateTime.UtcNow.AddHours(-3));File.SetLastWriteTimeUtc(s,DateTime.UtcNow.AddHours(-3));Scan(c,baseline:DateTime.UtcNow);Program.Check(!Directory.Exists(c.DispenseItems[0].SaveFolder)||Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==0,"old source copied with OnlyNew");Scan(c,baseline:DateTime.UtcNow.AddHours(-4));Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==1,"restart baseline incorrectly resets");}
 public static void TestSelectedParentIncludesChildrenOnly(){var c=Cfg(Fresh());c.DispenseItems[0].SubFolders=["partProcessed"];Source(c,"partProcessed/deep/Request_yes.xml");Source(c,"ES 2/Request_no.xml");Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==1,"selected subtree ignored");}
 public static void TestSameNameSameLengthDifferentSourceNoOverwrite(){var c=Cfg(Fresh());Source(c,"a/Request_same.xml","<root>1111111111</root>");Source(c,"b/Request_same.xml","<root>2222222222</root>");Scan(c);var files=Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml");Program.Check(files.Length==2,"same-name sources overwritten");Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==2,"idempotence broken");}
 public static void TestPartialXmlNeverVisible(){var c=Cfg(Fresh());Source(c,text:"<root><unfinished>broken");var r=Scan(c);Program.Check(Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==0,"partial XML published");Program.Check((int)r.GetType().GetProperty("Failed")!.GetValue(r)!>0,"failure invisible");}
 public static void TestCopyRecursiveRequestOnly(){var c=Cfg(Fresh());var s=Source(c);Source(c,"ES 2/notRequest.xml");Scan(c);var files=Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml");Program.Check(files.Length==1,"one Request XML expected");Program.Check(File.ReadAllText(files[0])==File.ReadAllText(s),"bytes differ");Program.Check(File.GetLastWriteTimeUtc(files[0])==File.GetLastWriteTimeUtc(s),"mtime not preserved");}
}
